"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_de"]=window.LC_CHUNKS["university_physics_de"]||{};window.LC_CHUNKS["university_physics_de"][41]={"university_physics_de:M41-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M41-L1 – Wellenleiter, geführte Moden und effektiver Brechungsindex<\/h1>\n<p><strong>Kursbereich:<\/strong> M41 – Master: Photonik und ultraschnelle Optik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M7: Wellenoptik; M33: Laser und\nPhotonen; M35: Materialphysik; M40 · <a\nhref=\"index.html?course=university_physics&amp;module=M40&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Aus der Moden-Phasenkonstante den\neffektiven Index ermitteln und zwischen Phasen- und\nGruppengeschwindigkeit unterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein integrierter optischer Wellenleiter hält Licht durch ein\nQuerprofil des Brechungsindex in einer geführten Mode. Statt die\nStrahlgeometrie allein zu verfolgen, löst man ein elektromagnetisches\nRandwertproblem: Feldprofile besitzen diskrete Quermoden und zugehörige\nPropagationskonstanten. Eine hohe Kernbrechzahl garantiert bei\nbeliebiger Geometrie nicht genau eine Mode.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Eine lokal monochromatische Mode trägt entlang\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>z<\/mi><annotation encoding=\"application/x-tex\">z<\/annotation><\/semantics><\/math>\nden Phasenfaktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">exp<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>i<\/mi><mi>β<\/mi><mi>z<\/mi><mo>−<\/mo><mi>i<\/mi><mi>ω<\/mi><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\exp(i\\beta z-i\\omega t)<\/annotation><\/semantics><\/math>.\nMit der Vakuumwellenzahl\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>k<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mi>/<\/mi><msub><mi>λ<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">k_0=2\\pi/\\lambda_0<\/annotation><\/semantics><\/math>\ndefiniert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>β<\/mi><mi>/<\/mi><msub><mi>k<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">n_{\\mathrm{eff}}=\\beta/k_0<\/annotation><\/semantics><\/math>\nden effektiven Phasenindex. Für eine verlustfreie, konventionelle\nIndexführung liegt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">l<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/msub><mo>&lt;<\/mo><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>&lt;<\/mo><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">n_{\\mathrm{clad}}&lt;n_{\\mathrm{eff}}&lt;n_{\\mathrm{core}}<\/annotation><\/semantics><\/math>.\nDer Gruppenindex ist dagegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><mi>c<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>β<\/mi><mi>/<\/mi><mi>d<\/mi><mi>ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n_g=c\\,d\\beta/d\\omega<\/annotation><\/semantics><\/math>;\ner ist bei Dispersion nicht automatisch gleich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">n_{\\mathrm{eff}}<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo>=<\/mo><mfrac><mrow><mn>2<\/mn><mi>π<\/mi><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><\/mrow><msub><mi>λ<\/mi><mn>0<\/mn><\/msub><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>v<\/mi><mrow><mi mathvariant=\"normal\">p<\/mi><mi mathvariant=\"normal\">h<\/mi><\/mrow><\/msub><mo>=<\/mo><mfrac><mi>ω<\/mi><mi>β<\/mi><\/mfrac><mo>=<\/mo><mfrac><mi>c<\/mi><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\beta=\\frac{2\\pi n_{\\mathrm{eff}}}{\\lambda_0},\\qquad v_{\\mathrm{ph}}=\\frac{\\omega}{\\beta}=\\frac{c}{n_{\\mathrm{eff}}}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für eine synthetische Mode bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>55<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_0=1{,}55\\,\\mathrm{\\mu m}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>70<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_{\\mathrm{eff}}=1{,}70<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo>=<\/mo><mn>6<\/mn><mo>,<\/mo><mn>89<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\beta=6{,}89\\,\\mathrm{\\mu m^{-1}}<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_{\\mathrm{core}}=2{,}0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">c<\/mi><mi mathvariant=\"normal\">l<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>45<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_{\\mathrm{clad}}=1{,}45<\/annotation><\/semantics><\/math>\nliegt dieser Index im erwarteten Bereich. Der Phasenweg einer Periode im\nWellenleiter beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mn>0<\/mn><\/msub><mi>/<\/mi><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>912<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_0/n_{\\mathrm{eff}}\\approx0{,}912\\,\\mathrm{\\mu m}<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt eine Mode als rein schematisches Feldprofil.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_315_DE.svg\"\nalt=\"Schematischer planarer Kern mit geführtem elektrischen Feldprofil und unterschiedlichen Brechzahlen.\" />\n<figcaption aria-hidden=\"true\">Schematischer planarer Kern mit geführtem\nelektrischen Feldprofil und unterschiedlichen Brechzahlen.<\/figcaption>\n<\/figure>\n<p><em>Eigenes schematisches Querschnittsmodell.<\/em><\/p>\n<p>Keine Modenlösung eines realen Bauelements.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>β<\/mi><annotation encoding=\"application/x-tex\">\\beta<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>50<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_{\\mathrm{eff}}=1{,}50<\/annotation><\/semantics><\/math>\nbei derselben Vakuumwellenlänge.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie verändert sich die Phasengeschwindigkeit bei größerem effektivem\nIndex?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Weshalb folgt der Gruppenindex nicht allein aus einer einzelnen\nPhasenmessung?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>50<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>1<\/mn><mo>,<\/mo><mn>55<\/mn><mo>≈<\/mo><mn>6<\/mn><mo>,<\/mo><mn>08<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\beta=2\\pi(1{,}50)/1{,}55\\approx6{,}08\\,\\mathrm{\\mu m^{-1}}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mrow><mi mathvariant=\"normal\">p<\/mi><mi mathvariant=\"normal\">h<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>c<\/mi><mi>/<\/mi><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">v_{\\mathrm{ph}}=c/n_{\\mathrm{eff}}<\/annotation><\/semantics><\/math>\nnimmt ab.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Der Gruppenindex benötigt die frequenzabhängige Steigung der\nPropagationskonstante.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Indexschranken gelten für das genannte einfache verlustfreie\nFührungsmodell. Leckmoden, komplexe Materialkonstanten, anisotrope oder\nmetamaterielle Strukturen und starke Dispersion erfordern erweiterte\nBehandlung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Ringresonatoren nutzen genau solche geführten Moden und deren\nfrequenzabhängige Phase. <a href=\"index.html?course=university_physics&amp;module=M41&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/3-46-photonic-materials-and-devices-spring-2006/pages/lecture-notes/\">MIT OCW – Photonic Materials and Devices: Lecture Notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L1 – Wellenleiter, geführte Moden und effektiver Brechungsindex · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.ocw.mit.edu/courses/18-369-mathematical-methods-in-nanophotonics-spring-2008/pages/readings/\">MIT OCW – Mathematical Methods in Nanophotonics: Readings<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L1 – Wellenleiter, geführte Moden und effektiver Brechungsindex · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M41-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M41-L2 – Ringresonatoren, freie Spektralbreite und Resonatorgüte<\/h1>\n<p><strong>Kursbereich:<\/strong> M41 – Master: Photonik und ultraschnelle Optik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M41-L1; M7: Interferenz und\nResonanz.<\/p>\n<p><strong>Lernziel:<\/strong> Resonanzabstand und Güte aus geometrischer\nLänge, Gruppenindex und Linienbreite bestimmen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Im Ringresonator bildet eine Wellenleitermode nach jedem Umlauf\nerneut eine komplexe Amplitude. Konstruktive Phasenbedingung erzeugt\ndiskrete Resonanzen. Zwei Messgrößen müssen getrennt bleiben: Die freie\nSpektralbreite (FSR) beschreibt den Abstand benachbarter Resonanzen; die\nLinienbreite einer einzelnen Resonanz legt ihre spektrale Selektivität\nfest.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Bei Umfang\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">L=2\\pi R<\/annotation><\/semantics><\/math>\ngilt als Resonanzbedingung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>ω<\/mi><mi>m<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>L<\/mi><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mi>m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\beta(\\omega_m)L=2\\pi m<\/annotation><\/semantics><\/math>.\nDie Ableitung nach\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>m<\/mi><annotation encoding=\"application/x-tex\">m<\/annotation><\/semantics><\/math>\nliefert lokal\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>ν<\/mi><mo>≈<\/mo><mi>c<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>n<\/mi><mi>g<\/mi><\/msub><mi>L<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\nu\\approx c/(n_gL)<\/annotation><\/semantics><\/math>,\nwobei der <strong>Gruppenindex<\/strong>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><mi>c<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>β<\/mi><mi>/<\/mi><mi>d<\/mi><mi>ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n_g=c\\,d\\beta/d\\omega<\/annotation><\/semantics><\/math>\ndie Dispersion berücksichtigt. In Wellenlängeneinheiten ergibt sich für\nkleine Abstände\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>λ<\/mi><mo>≈<\/mo><msubsup><mi>λ<\/mi><mn>0<\/mn><mn>2<\/mn><\/msubsup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>n<\/mi><mi>g<\/mi><\/msub><mi>L<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\lambda\\approx\\lambda_0^2/(n_gL)<\/annotation><\/semantics><\/math>.\nFür eine schmale isolierte Resonanz ist die geladene Güte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>≈<\/mo><msub><mi>λ<\/mi><mn>0<\/mn><\/msub><mi>/<\/mi><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>λ<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">W<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">M<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">Q\\approx\\lambda_0/\\Delta\\lambda_{\\mathrm{FWHM}}<\/annotation><\/semantics><\/math>;\ndie Einkopplung beeinflusst diese Güte.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>λ<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">S<\/mi><mi mathvariant=\"normal\">R<\/mi><\/mrow><\/msub><mo>≃<\/mo><mfrac><msubsup><mi>λ<\/mi><mn>0<\/mn><mn>2<\/mn><\/msubsup><mrow><msub><mi>n<\/mi><mi>g<\/mi><\/msub><mspace width=\"0.167em\"><\/mspace><mn>2<\/mn><mi>π<\/mi><mi>R<\/mi><\/mrow><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>Q<\/mi><mo>≃<\/mo><mfrac><msub><mi>λ<\/mi><mn>0<\/mn><\/msub><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>λ<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">W<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">M<\/mi><\/mrow><\/msub><\/mrow><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\lambda_{\\mathrm{FSR}}\\simeq\\frac{\\lambda_0^2}{n_g\\,2\\pi R},\\qquad Q\\simeq\\frac{\\lambda_0}{\\Delta\\lambda_{\\mathrm{FWHM}}}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mn>10<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">R=10\\,\\mathrm{\\mu m}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><mn>4<\/mn><mo>,<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_g=4{,}0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>55<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_0=1{,}55\\,\\mathrm{\\mu m}<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>λ<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">S<\/mi><mi mathvariant=\"normal\">R<\/mi><\/mrow><\/msub><mo>≈<\/mo><mn>9<\/mn><mo>,<\/mo><mn>56<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\lambda_{\\mathrm{FSR}}\\approx9{,}56\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>.\nFür eine beobachtete FWHM von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>80<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">0{,}80\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>≈<\/mo><mn>1550<\/mn><mi>/<\/mi><mn>0<\/mn><mo>,<\/mo><mn>80<\/mn><mo>=<\/mo><mn>1938<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q\\approx1550/0{,}80=1938<\/annotation><\/semantics><\/math>.\nDie Grafik trennt geometrische Umlauflänge, Resonanzabstand und\nLinienbreite. Die Werte sind synthetisch und keine Verlustangabe eines\nHerstellers.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_249_DE.svg\"\nalt=\"Ring-Wellenleiter mit optischem Bus und getrenntem schematischem Resonanzspektrum.\" />\n<figcaption aria-hidden=\"true\">Ring-Wellenleiter mit optischem Bus und\ngetrenntem schematischem Resonanzspektrum.<\/figcaption>\n<\/figure>\n<p><em>Eigene Lehrzeichnung; FSR und FWHM werden getrennt\nskaliert.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Was geschieht mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>λ<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">S<\/mi><mi mathvariant=\"normal\">R<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\lambda_{\\mathrm{FSR}}<\/annotation><\/semantics><\/math>,\nwenn der Radius verdoppelt wird?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum muss bei der FSR-Berechnung die Dispersion berücksichtigt\nwerden?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Wie groß wäre\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Q<\/mi><annotation encoding=\"application/x-tex\">Q<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>λ<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">W<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">M<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>40<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\lambda_{\\mathrm{FWHM}}=0{,}40\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bei unveränderten übrigen Größen halbiert sich die FSR auf rund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4<\/mn><mo>,<\/mo><mn>78<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">4{,}78\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die Frequenzableitung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>β<\/mi><annotation encoding=\"application/x-tex\">\\beta<\/annotation><\/semantics><\/math>\nbestimmt die Abstände benachbarter Moden; der Phasenindex allein reicht\nnicht.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><mn>1550<\/mn><mi>/<\/mi><mn>0<\/mn><mo>,<\/mo><mn>40<\/mn><mo>≈<\/mo><mn>3875<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q=1550/0{,}40\\approx3875<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Näherung erfordert lokal schwache Variation des Gruppenindex,\nkleine FSR im Verhältnis zur Wellenlänge und eine getrennte Linienform.\nThermische Drift, Rückstreuung, Doppelresonanzen und komplexe Kopplung\nerschweren reale Spektren.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>An Resonatoren wird deutlich, wie Materialdispersion optische Zeit-\nund Frequenzskalen bestimmt. <a\nhref=\"index.html?course=university_physics&amp;module=M41&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/3-46-photonic-materials-and-devices-spring-2006/pages/lecture-notes/\">MIT OCW – Photonic Materials and Devices: Lecture Notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L2 – Ringresonatoren, freie Spektralbreite und Resonatorgüte · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.ocw.mit.edu/courses/18-369-mathematical-methods-in-nanophotonics-spring-2008/pages/readings/\">MIT OCW – Mathematical Methods in Nanophotonics: Readings<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L2 – Ringresonatoren, freie Spektralbreite und Resonatorgüte · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://optics.ansys.com/hc/en-us/articles/360042800293-Ring-resonator-getting-started-Design-and-initial-simulation\">Ansys Optics – Photonics: Ring Resonator Modeling (Ansys Optics)<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L2 – Ringresonatoren, freie Spektralbreite und Resonatorgüte · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M41-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M41-L3 – Ultrakurze Pulse, Zeit-Bandbreite und Dispersion<\/h1>\n<p><strong>Kursbereich:<\/strong> M41 – Master: Photonik und ultraschnelle Optik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M41-L2; M7: Fourier-Optik; M31:\nnumerische Fouriermethoden.<\/p>\n<p><strong>Lernziel:<\/strong> Die minimale spektrale Bandbreite eines\ntransformlimitierten Gauß-Pulses berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein kurzer Lichtimpuls ist keine einzelne monochromatische\nSchwingung. Seine Hüllkurve entsteht aus der kohärenten Überlagerung\neines Spektrums. Je kürzer ein Puls bei festgelegter Form zeitlich ist,\ndesto breiter muss sein Frequenzspektrum sein. Eine spektrale Phase kann\nden Puls zusätzlich verlängern, ohne die spektrale Intensitätsbreite zu\nändern.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für einen transformlimitierten, unchirpten Gauß-Puls ist das Produkt\nder Intensitäts-FWHM in Zeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t<\/annotation><\/semantics><\/math>\nund gewöhnlicher Frequenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>ν<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\nu<\/annotation><\/semantics><\/math>\ngleich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mi>/<\/mi><mi>π<\/mi><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>441<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2\\ln 2/\\pi\\approx0{,}441<\/annotation><\/semantics><\/math>.\nDer Koeffizient gilt <strong>nicht<\/strong> allgemein für beliebige\nPulsformen oder für RMS-Breiten. Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>λ<\/mi><mo>≪<\/mo><msub><mi>λ<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\lambda\\ll\\lambda_0<\/annotation><\/semantics><\/math>\nkann\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>λ<\/mi><mo>≈<\/mo><msubsup><mi>λ<\/mi><mn>0<\/mn><mn>2<\/mn><\/msubsup><mi mathvariant=\"normal\">Δ<\/mi><mi>ν<\/mi><mi>/<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\lambda\\approx\\lambda_0^2\\Delta\\nu/c<\/annotation><\/semantics><\/math>\nangenähert werden. Dispersive Propagation verändert die relative\nspektrale Phase; sie kann zeitliche Chirps verursachen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>t<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">W<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">M<\/mi><\/mrow><\/msub><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>ν<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">W<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">M<\/mi><\/mrow><\/msub><mo>=<\/mo><mfrac><mrow><mn>2<\/mn><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/mrow><mi>π<\/mi><\/mfrac><mo>≃<\/mo><mn>0.441<\/mn><mspace width=\"1.0em\"><\/mspace><mtext mathvariant=\"normal\">(transformationsbegrenzter Gaußpuls)<\/mtext><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t_{\\mathrm{FWHM}}\\,\\Delta\\nu_{\\mathrm{FWHM}}=\\frac{2\\ln 2}{\\pi}\\simeq0.441\\quad\\text{(transformationsbegrenzter Gaußpuls)}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Ein transformlimitierter Gauß-Puls mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><mo>=<\/mo><mn>100<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t=100\\,\\mathrm{fs}<\/annotation><\/semantics><\/math>\nbesitzt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>ν<\/mi><mo>≈<\/mo><mn>4<\/mn><mo>,<\/mo><mn>41<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">T<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\nu\\approx4{,}41\\,\\mathrm{THz}<\/annotation><\/semantics><\/math>.\nBei einer Zentralwellenlänge von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>800<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">800\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>\nentspricht dies lokal etwa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>9<\/mn><mo>,<\/mo><mn>42<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">9{,}42\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>\nBandbreite. Die Grafik trennt zeitliche Pulsintensität und spektrale\nIntensität; die beiden horizontalen Achsen sind nicht dieselbe\nGröße.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_302_DE.svg\"\nalt=\"Zwei separate Gaußkurven für Intensität über Zeit und Frequenz mit den jeweiligen FWHM-Breiten.\" />\n<figcaption aria-hidden=\"true\">Zwei separate Gaußkurven für Intensität\nüber Zeit und Frequenz mit den jeweiligen FWHM-Breiten.<\/figcaption>\n<\/figure>\n<p><em>Eigene Modellkurven für transformlimitierte Gauß-Pulse.<\/em><\/p>\n<p>Keine gemessenen Laserdaten.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche minimale\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>ν<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\nu<\/annotation><\/semantics><\/math>\nhat ein\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>50<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">50\\,\\mathrm{fs}<\/annotation><\/semantics><\/math>-Gauß-Puls?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum kann ein spektraler Phasenchirp den Puls bei gleicher\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>ν<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\nu<\/annotation><\/semantics><\/math>\nverlängern?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Gilt der Zahlenfaktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>441<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}441<\/annotation><\/semantics><\/math>\nfür einen Sech-Puls?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Rund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>8<\/mn><mo>,<\/mo><mn>82<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">T<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">8{,}82\\,\\mathrm{THz}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die Frequenzkomponenten treffen mit anderer relativer Verzögerung\nbeziehungsweise Phase ein.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nein. Das Zeit-Bandbreite-Produkt hängt von Pulsform und\nBreitenkonvention ab.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Keine Aussage zur Pulsenergie, Spitzenintensität oder zur praktischen\nKomprimierbarkeit eines realen Lasers. Nichtlineare Propagation,\nräumliche Kopplung, Restchirp und endliche Messauflösung können die\neinfache Fouriergrenze überlagern.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Ultrakurze Impulse werden unter anderem mit Elektronenstrahlen und\nRöntgenlasern gekoppelt. <a href=\"index.html?course=university_physics&amp;module=M41&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/6-977-ultrafast-optics-spring-2005/pages/lecture-notes/\">MIT OCW – Ultrafast Optics: Lecture Notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L3 – Ultrakurze Pulse, Zeit-Bandbreite und Dispersion · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M41-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M41-L4 – Freie-Elektronen-Laser und Undulatorresonanz<\/h1>\n<p><strong>Kursbereich:<\/strong> M41 – Master: Photonik und ultraschnelle Optik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M36: Beschleuniger; M41-L3:\nPulsphysik; M32: XFEL-Instrumente.<\/p>\n<p><strong>Lernziel:<\/strong> Die zentrale Undulator-Resonanzwellenlänge\nin einem idealisierten Elektronenstrahl berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein Freie-Elektronen-Laser erzeugt Strahlung mit relativistischen\nElektronen und einem periodischen Magnetfeld statt eines gebundenen\natomaren Laserübergangs. Das Undulatormagnetfeld zwingt die Elektronen\nauf eine kleine transversale Oszillation. Die Phasenanpassung zwischen\nStrahlung und Elektronenbewegung bestimmt die bevorzugte Wellenlänge;\ndie Ausbildung von Lasergewinn ist ein zusätzlicher physikalischer\nProzess.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für einen idealen planaren Undulator, die Grundharmonische und\nBeobachtung entlang der Strahlachse gilt in ultrarelativistischer\nNäherung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>r<\/mi><\/msub><mo>=<\/mo><msub><mi>λ<\/mi><mi>u<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><msup><mi>K<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><msup><mi>γ<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_r=\\lambda_u(1+K^2/2)/(2\\gamma^2)<\/annotation><\/semantics><\/math>.\nDabei ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>λ<\/mi><mi>u<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\lambda_u<\/annotation><\/semantics><\/math>\ndie Undulatorperiode,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>K<\/mi><annotation encoding=\"application/x-tex\">K<\/annotation><\/semantics><\/math>\nder dimensionslose Undulatorparameter und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>γ<\/mi><annotation encoding=\"application/x-tex\">\\gamma<\/annotation><\/semantics><\/math>\nder Lorentzfaktor des Elektrons. Außerhalb der Achse kommt ein\nWinkelterm hinzu. Die Resonanzformel garantiert weder Microbunching noch\nexponentielle FEL-Verstärkung.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>r<\/mi><\/msub><mo>≃<\/mo><mfrac><msub><mi>λ<\/mi><mi>u<\/mi><\/msub><mrow><mn>2<\/mn><msup><mi>γ<\/mi><mn>2<\/mn><\/msup><\/mrow><\/mfrac><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mfrac><msup><mi>K<\/mi><mn>2<\/mn><\/msup><mn>2<\/mn><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mspace width=\"2.0em\"><\/mspace><mtext mathvariant=\"normal\">(planar, auf der Achse, Grundwelle)<\/mtext><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_r\\simeq\\frac{\\lambda_u}{2\\gamma^2}\\left(1+\\frac{K^2}{2}\\right)\\qquad\\text{(planar, auf der Achse, Grundwelle)}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für rein illustrative Werte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>u<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>030<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_u=0{,}030\\,\\mathrm m<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>γ<\/mi><mo>=<\/mo><msup><mn>10<\/mn><mn>4<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\gamma=10^4<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>K<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">K=1<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>r<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>25<\/mn><mo>×<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>10<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>225<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_r=2{,}25\\times10^{-10}\\,\\mathrm m=0{,}225\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>.\nEine Verdopplung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>γ<\/mi><annotation encoding=\"application/x-tex\">\\gamma<\/annotation><\/semantics><\/math>\nwürde die Resonanzwellenlänge bei konstantem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>K<\/mi><annotation encoding=\"application/x-tex\">K<\/annotation><\/semantics><\/math>\nauf ein Viertel senken. Die Grafik zeigt Magnetperioden, Elektronenbahn\nund die schematische emittierte Welle.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_305_DE.svg\"\nalt=\"Periodisches Undulator-Magnetfeld, oszillierende Elektronenbahn und schematische Röntgenemission.\" />\n<figcaption aria-hidden=\"true\">Periodisches Undulator-Magnetfeld,\noszillierende Elektronenbahn und schematische\nRöntgenemission.<\/figcaption>\n<\/figure>\n<p><em>Eigenes, nicht maßstäbliches FEL-Prinzipbild; keine\nAnlagenzeichnung.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bestimme\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>λ<\/mi><mi>r<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\lambda_r<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>K<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">K=0<\/annotation><\/semantics><\/math>\nbei sonst gleichen Parametern.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie skaliert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>λ<\/mi><mi>r<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\lambda_r<\/annotation><\/semantics><\/math>\nmit dem Lorentzfaktor bei konstantem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>K<\/mi><annotation encoding=\"application/x-tex\">K<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist die Resonanzformel kein Nachweis tatsächlicher\nLaser-Verstärkung?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>150<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">0{,}150\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>r<\/mi><\/msub><mo>∝<\/mo><msup><mi>γ<\/mi><mrow><mi>−<\/mi><mn>2<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_r\\propto\\gamma^{-2}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Gewinn erfordert zusätzlich Kopplung, Strahlqualität und geeignete\nlongitudinale Phasenentwicklung.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Reale Anlagen nutzen endliche Emittanzen, Energieverteilungen,\nResonanzharmonische, SASE oder Seed-Verfahren und komplexe\nStrahltransportmodelle. Die Beispielzahlen sind nicht als aktuelle\nBetriebsdaten einer konkreten XFEL-Anlage zu verwenden.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Das erzeugte kohärente Röntgenlicht ermöglicht Beugungsexperimente an\nkleinen Proben. <a href=\"index.html?course=university_physics&amp;module=M41&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.xfel.eu/facility/beamlines/index_eng.html\">European XFEL – Beamlines<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L4 – Freie-Elektronen-Laser und Undulatorresonanz · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://lcls.slac.stanford.edu/instruments/cxi/experimental-methods\">SLAC LCLS – CXI Experimental Methods<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L4 – Freie-Elektronen-Laser und Undulatorresonanz · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M41-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M41-L5 – Kohärente Röntgenbeugung und Streuvektoren<\/h1>\n<p><strong>Kursbereich:<\/strong> M41 – Master: Photonik und ultraschnelle Optik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M41-L4; M35: Kristallbeugung; M31:\ninverse Probleme.<\/p>\n<p><strong>Lernziel:<\/strong> Den Betrag des elastischen Streuvektors\nberechnen und die fehlende Phaseninformation bei Intensitätsmessungen\nerklären.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Kohärente Röntgenstrahlen interferieren nach Streuung an\nverschiedenen Punkten einer Probe. Fernfeld-Beugungsbilder kodieren\nräumliche Frequenzen der Elektronendichte. Detektoren registrieren in\nder Regel Intensität, nicht das komplexe Feld mit seiner Phase. Das\nmacht die Rückgewinnung der Probenstruktur zu einem inversen\nProblem.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Bei elastischer Streuung bleibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi mathvariant=\"bold-italic\">𝒌<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi mathvariant=\"bold-italic\">𝒌<\/mi><mi>s<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mi>/<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|\\mathbf k_i|=|\\mathbf k_s|=2\\pi/\\lambda<\/annotation><\/semantics><\/math>;\nder Streuvektor ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝒒<\/mi><mo>=<\/mo><msub><mi mathvariant=\"bold-italic\">𝒌<\/mi><mi>s<\/mi><\/msub><mo>−<\/mo><msub><mi mathvariant=\"bold-italic\">𝒌<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf q=\\mathbf k_s-\\mathbf k_i<\/annotation><\/semantics><\/math>.\nBei einem Gesamt-Streuwinkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>θ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\theta<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mn>4<\/mn><mi>π<\/mi><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mi>/<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">q=4\\pi\\sin\\theta/\\lambda<\/annotation><\/semantics><\/math>.\nIn der kinematischen Einmalstreunäherung gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒒<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>∝<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mover><mi>ρ<\/mi><mo accent=\"true\">̃<\/mo><\/mover><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒒<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">I(\\mathbf q)\\propto|\\widetilde\\rho(\\mathbf q)|^2<\/annotation><\/semantics><\/math>.\nDamit bleibt die Phase von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mover><mi>ρ<\/mi><mo accent=\"true\">̃<\/mo><\/mover><annotation encoding=\"application/x-tex\">\\widetilde\\rho<\/annotation><\/semantics><\/math>\nzunächst unbekannt; kohärente Beugungsbildgebung benötigt zusätzliche\nNebenbedingungen und Algorithmen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi mathvariant=\"bold-italic\">𝒌<\/mi><mi>s<\/mi><\/msub><mo>−<\/mo><msub><mi mathvariant=\"bold-italic\">𝒌<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mfrac><mrow><mn>4<\/mn><mi>π<\/mi><\/mrow><mi>λ<\/mi><\/mfrac><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>I<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒒<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>∝<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mover><mi>ρ<\/mi><mo accent=\"true\">̃<\/mo><\/mover><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒒<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">q=|\\mathbf k_s-\\mathbf k_i|=\\frac{4\\pi}{\\lambda}\\sin\\theta,\\qquad I(\\mathbf q)\\propto|\\widetilde\\rho(\\mathbf q)|^2.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>100<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=0{,}100\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>15<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=15^\\circ<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>≈<\/mo><mn>32<\/mn><mo>,<\/mo><mn>52<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">q\\approx32{,}52\\,\\mathrm{nm^{-1}}<\/annotation><\/semantics><\/math>.\nDie zugehörige charakteristische Raumskala\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><mi>/<\/mi><mi>q<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi/q<\/annotation><\/semantics><\/math>\nliegt bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>193<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">0{,}193\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt ein Einfalls-/Streugeometrie-Dreieck und ein rein\nsynthetisches Beugungsspektrum; letzteres ist keine Rekonstruktion einer\nProbe.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_044_DE.svg\"\nalt=\"Einfallender und elastisch gestreuter Röntgenstrahl sowie synthetisches Beugungsmuster.\" />\n<figcaption aria-hidden=\"true\">Einfallender und elastisch gestreuter\nRöntgenstrahl sowie synthetisches Beugungsmuster.<\/figcaption>\n<\/figure>\n<p><em>Didaktische Darstellung ohne realen Detektordatensatz.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>q<\/mi><annotation encoding=\"application/x-tex\">q<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>30<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=30^\\circ<\/annotation><\/semantics><\/math>\nund unveränderte Wellenlänge.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum liefern Intensitätsdetektoren das komplexe Streufeld nicht\ndirekt?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Was ist der Unterschied zwischen Raumskala\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><mi>/<\/mi><mi>q<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi/q<\/annotation><\/semantics><\/math>\nund garantierter Bildauflösung?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mn>62<\/mn><mo>,<\/mo><mn>83<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">q=62{,}83\\,\\mathrm{nm^{-1}}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die Messung erfasst das Betragsquadrat; die komplexe Phase ist darin\nnicht separat gespeichert.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die realisierbare Auflösung hängt zusätzlich von Winkelabdeckung,\nSignal, Rauschen, Strahlungsschäden und Rekonstruktionsannahmen ab.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Fourier-Beziehung ist ein Modell der kinematischen kohärenten\nStreuung. Mehrfachstreuung, Partialkohärenz, Detektorlücken, endliche\nProben und Probenschäden können die Inversion wesentlich verändern.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Ultraschnelle Streuexperimente kombinieren oft Beugung mit einer\noptischen Anregung zu einstellbaren Verzögerungszeiten. <a\nhref=\"index.html?course=university_physics&amp;module=M41&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://lcls.slac.stanford.edu/instruments/cxi/experimental-methods\">SLAC LCLS – CXI Experimental Methods<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L5 – Kohärente Röntgenbeugung und Streuvektoren · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.ocw.mit.edu/courses/18-369-mathematical-methods-in-nanophotonics-spring-2008/pages/readings/\">MIT OCW – Mathematical Methods in Nanophotonics: Readings<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L5 – Kohärente Röntgenbeugung und Streuvektoren · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M41-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M41-L6 – Pump-Probe-Messungen, Zeitjitter und Instrumentantwort<\/h1>\n<p><strong>Kursbereich:<\/strong> M41 – Master: Photonik und ultraschnelle Optik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M41-L3; M41-L5; M32:\nPump-Probe-Messtechnik.<\/p>\n<p><strong>Lernziel:<\/strong> Eine idealisierte zeitliche\nInstrumentantwort aus Pump-, Probe- und Jitterbreiten bestimmen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Beim Pump-Probe-Prinzip regt ein Pumpimpuls einen transienten Zustand\nan; ein zeitlich verzögerter Probeimpuls erfasst ein davon abhängiges\nSignal. Das Variationsexperiment scannt die Verzögerung. Die messbare\nZeitauflösung folgt nicht allein aus der Dauer des kürzesten Impulses,\nda beide Pulse und der relative Ankunftszeitjitter beitragen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für voneinander unabhängige Gaußsche Pump- und\nProbe-Intensitätsprofile sowie unabhängigen Gauß-Jitter ist die\nzeitliche Kreuzkorrelation erneut gaußförmig. Ihre Varianzen addieren\nsich. Da die Umrechnung zwischen Gaußstandardabweichung und FWHM für\nalle drei Beiträge gleich ist, dürfen auch deren FWHM-Werte quadratisch\naddiert werden. Das funktioniert nicht pauschal für asymmetrische\nProfile oder korrelierten Jitter.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>t<\/mi><mrow><mi mathvariant=\"normal\">I<\/mi><mi mathvariant=\"normal\">R<\/mi><mi mathvariant=\"normal\">F<\/mi><\/mrow><\/msub><mo>≃<\/mo><msqrt><mrow><mi mathvariant=\"normal\">Δ<\/mi><msubsup><mi>t<\/mi><mrow><mi mathvariant=\"normal\">p<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">p<\/mi><\/mrow><mn>2<\/mn><\/msubsup><mo>+<\/mo><mi mathvariant=\"normal\">Δ<\/mi><msubsup><mi>t<\/mi><mrow><mi mathvariant=\"normal\">p<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">b<\/mi><mi mathvariant=\"normal\">e<\/mi><\/mrow><mn>2<\/mn><\/msubsup><mo>+<\/mo><mi mathvariant=\"normal\">Δ<\/mi><msubsup><mi>t<\/mi><mrow><mi mathvariant=\"normal\">j<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mn>2<\/mn><\/msubsup><\/mrow><\/msqrt><mspace width=\"1.0em\"><\/mspace><mtext mathvariant=\"normal\">(unabhängige gaußförmige FWHM-Beiträge)<\/mtext><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t_{\\mathrm{IRF}}\\simeq\\sqrt{\\Delta t_{\\mathrm{pump}}^2+\\Delta t_{\\mathrm{probe}}^2+\\Delta t_{\\mathrm{jitter}}^2}\\quad\\text{(unabhängige gaußförmige FWHM-Beiträge)}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>50<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">50\\,\\mathrm{fs}<\/annotation><\/semantics><\/math>\nPump-FWHM,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>70<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">70\\,\\mathrm{fs}<\/annotation><\/semantics><\/math>\nProbe-FWHM und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>30<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">30\\,\\mathrm{fs}<\/annotation><\/semantics><\/math>\nunabhängigem Jitter folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>t<\/mi><mrow><mi mathvariant=\"normal\">I<\/mi><mi mathvariant=\"normal\">R<\/mi><mi mathvariant=\"normal\">F<\/mi><\/mrow><\/msub><mo>=<\/mo><msqrt><mn>8300<\/mn><\/msqrt><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><mo>≈<\/mo><mn>91<\/mn><mo>,<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t_{\\mathrm{IRF}}=\\sqrt{8300}\\,\\mathrm{fs}\\approx91{,}1\\,\\mathrm{fs}<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt Anregung und Abfrage bei einer variablen Verzögerung\nsowie eine verbreiterte Instrumentantwort.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_227_DE.svg\"\nalt=\"Pump- und Probeimpuls mit variabler Verzögerung sowie gaußförmige Instrumentantwort.\" />\n<figcaption aria-hidden=\"true\">Pump- und Probeimpuls mit variabler\nVerzögerung sowie gaußförmige Instrumentantwort.<\/figcaption>\n<\/figure>\n<p><em>Eigenes idealisiertes Zeitdiagramm.<\/em><\/p>\n<p>Keine Messung an einer realen Anlage.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist die Antwortbreite bei verschwindendem Jitter?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum wird nicht die gewöhnliche arithmetische Summe der Pulsdauern\nverwendet?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Wann versagt die quadratische FWHM-Addition?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><msup><mn>50<\/mn><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mn>70<\/mn><mn>2<\/mn><\/msup><\/mrow><\/msqrt><mo>≈<\/mo><mn>86<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sqrt{50^2+70^2}\\approx86{,}0\\,\\mathrm{fs}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die unabhängigen Gaußbeiträge falten sich; dabei addieren sich die\nVarianzen.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Bei Nicht-Gaußformen, Korrelationen oder systematischen Zeitfehlern\nist ein anderes Antwortmodell nötig.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Modell ist kein realer Timing-Budget-Nachweis. Nichtlineare\nProbendynamik, Instabilitäten, Puls-Chirp, Synchronisierung und die\nAuswertung einzelner Schüsse können das gemessene Signal prägen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Im abschließenden Modulabschnitt geht es um die räumliche Steuerung\nphotonischer Felder durch periodische Medien. <a\nhref=\"index.html?course=university_physics&amp;module=M41&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/6-977-ultrafast-optics-spring-2005/pages/lecture-notes/\">MIT OCW – Ultrafast Optics: Lecture Notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L6 – Pump-Probe-Messungen, Zeitjitter und Instrumentantwort · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC6510196/\">LCLS – Pump–Probe Experimental Methodology<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L6 – Pump-Probe-Messungen, Zeitjitter und Instrumentantwort · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://lcls.slac.stanford.edu/instruments/cxi/experimental-methods\">SLAC LCLS – CXI Experimental Methods<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L6 – Pump-Probe-Messungen, Zeitjitter und Instrumentantwort · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M41-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M41-L7 – Photonische Kristalle, periodischer Index und Bragg-Bandlücken<\/h1>\n<p><strong>Kursbereich:<\/strong> M41 – Master: Photonik und ultraschnelle Optik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M41-L1: Moden; M41-L2: Resonanz;\nM35: Bloch-Zustände.<\/p>\n<p><strong>Lernziel:<\/strong> Einen vereinfachten\nBragg-Wellenlängenbereich aus Periodizität und effektivem Index\nabschätzen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein photonischer Kristall besitzt eine räumlich periodische\ndielektrische Struktur. Entlang einer Periodenrichtung lassen sich\nFelder als Bloch-Moden auffassen. An Brillouin-Zonengrenzen können\ngegenläufige Wellen durch die periodische Modulation gekoppelt werden.\nFür ausreichend wirksame Indexmodulation entstehen Bereiche verminderter\noder verbotener Ausbreitung.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für eine einfache eindimensionale, schwach modulierte Bragg-Struktur\nkann das Zentrum einer ersten Rückstreuresonanz grob über\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>β<\/mi><mo>≈<\/mo><mn>2<\/mn><mi>π<\/mi><mi>/<\/mi><mi>a<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\beta\\approx 2\\pi/a<\/annotation><\/semantics><\/math>\nbeschrieben werden. Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo>≈<\/mo><mn>2<\/mn><mi>π<\/mi><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mi>/<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\beta\\approx2\\pi n_{\\mathrm{eff}}/\\lambda<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>B<\/mi><\/msub><mo>≈<\/mo><mn>2<\/mn><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mi>a<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_B\\approx2n_{\\mathrm{eff}}a<\/annotation><\/semantics><\/math>.\nDie Beziehung benennt die Bragg-Resonanzmitte, nicht automatisch die\nvollständige Breite oder das sichere Vorhandensein einer photonic band\ngap. Diese hängen von Indexkontrast, Polarisation, Geometrie und\nModenkopplung ab.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>β<\/mi><mo>≃<\/mo><mfrac><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><mi>a<\/mi><\/mfrac><mspace width=\"1.0em\"><\/mspace><mo>⇒<\/mo><mspace width=\"1.0em\"><\/mspace><msub><mi>λ<\/mi><mi>B<\/mi><\/msub><mo>≃<\/mo><mn>2<\/mn><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mi>a<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\beta\\simeq\\frac{2\\pi}{a}\\quad\\Longrightarrow\\quad\\lambda_B\\simeq2n_{\\mathrm{eff}}a.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>250<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">a=250\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>50<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_{\\mathrm{eff}}=1{,}50<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>B<\/mi><\/msub><mo>≈<\/mo><mn>750<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_B\\approx750\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>.\nBei gleicher angenommener Mode und auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>300<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">300\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>\nvergrößerter Periode läge die Abschätzung bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>900<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">900\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>.\nDie Grafik verbindet die reale Indexperiodizität mit einer schematischen\nDispersionsaufspaltung nahe einer Zonengrenze.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_215_DE.svg\"\nalt=\"Periodische Brechzahlschichten und schematische Aufspaltung zweier Dispersionszweige an der Zonengrenze.\" />\n<figcaption aria-hidden=\"true\">Periodische Brechzahlschichten und\nschematische Aufspaltung zweier Dispersionszweige an der\nZonengrenze.<\/figcaption>\n<\/figure>\n<p><em>Eigens gezeichnete Konzeptgrafik, keine berechnete\nBandstruktur.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bestimme\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>λ<\/mi><mi>B<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\lambda_B<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>200<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">a=200\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_{\\mathrm{eff}}=1{,}5<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche physikalischen Größen beeinflussen die Bandlückenbreite?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum folgt aus der Bragg-Wellenlänge noch keine vollständige\ndreidimensionale Bandlücke?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>600<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">600\\,\\mathrm{nm}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Zum Beispiel Indexkontrast, Geometrie, Polarisation und räumliche\nModenkopplung.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die Formel untersucht nur eine idealisierte periodische Richtung und\neine einfache Modenpaarung.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Starke Modulation, mehrdimensionale Kristalle, anisotrope Medien und\nDispersion erfordern volle Maxwell-Eigenwertprobleme. Diese Modellgrafik\nbeweist keine Bandlücke und ersetzt keine optische\nTransmissionsmessung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>M41 schließt die photonische Vertiefung von geführten Moden über\nultrakurze Pulse bis zu periodischen Strukturen ab.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/3-46-photonic-materials-and-devices-spring-2006/pages/lecture-notes/\">MIT OCW – Photonic Materials and Devices: Lecture Notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L7 – Photonische Kristalle, periodischer Index und Bragg-Bandlücken · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.ocw.mit.edu/courses/18-369-mathematical-methods-in-nanophotonics-spring-2008/pages/readings/\">MIT OCW – Mathematical Methods in Nanophotonics: Readings<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M41-L7 – Photonische Kristalle, periodischer Index und Bragg-Bandlücken · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
